'use strict';
// Batch-owned authoring data. These are logical objects/functions, not deployed services.
const {problem,contract,component,builder}=require('./study-solution-author.cjs');
// Each approach owns its command (and optional read-only) contract, its acceptance cases and
// the case IDs each stage establishes. A case carries evidence only when it names a reference
// test that exercises that approach's mechanism.
function author(spec){
 const p=problem(spec.id,spec.title,spec.scope,spec.requirements.map((text,i)=>({id:'r'+i,text})),spec.references.map((r,i)=>({id:'ref'+i,title:r[0],url:r[1],supports:r[2],scope:'background'})));
 const testFile='tools/simulatte/study-reference/batch-'+spec.batch+'-mechanisms.test.mjs',mode=spec.local===false?'request-response':'local-call';
 for(const a of spec.approaches){
  const prefix=spec.id.toLowerCase()+'.'+a.id,command=a.command||spec.command,read=a.read||spec.read||null,readAt=read?(read.at||'owner'):null,caseIds=new Set(a.cases.map(c=>c.id));
  const checks=ids=>{if(!ids?.length)throw Error(prefix+': stage needs acceptance case IDs');for(const id of ids)if(!caseIds.has(id))throw Error(prefix+': unknown case '+id);return ids;};
  contract(p,prefix+'.command',command.request,command.response);
  if(read)contract(p,prefix+'.read',read.request,read.response);
  component(p,prefix+'.caller',spec.caller||'Caller','client','Invoke the documented API and retain returned outcomes.',['caller-owned input']);
  component(p,prefix+'.owner',a.owner,'module',a.responsibility,a.state);
  const b=builder(p,a.id,a.title,a.choose,a.tradeoffs,[spec.assumption,'All added requirements and walkthroughs are authored practice. Graphs specify design; reference tests prove only named bounded mechanisms.']);
  b.stage('Expose '+a.owner,a.question,a.responsibility,s=>{s.add('caller',prefix+'.caller');s.add('owner',prefix+'.owner');s.link('command','caller','owner',prefix+'.command',mode);if(readAt==='owner')s.link('read','caller','owner',prefix+'.read',mode);},[a.invariant],checks(a.checks));
  for(const n of a.steps){
   const cid=prefix+'.'+n.id;
   contract(p,cid,n.request,n.response);
   component(p,cid,n.label,n.kind||'module',n.reason,n.state);
   b.stage(n.title,n.question,n.reason,s=>{s.add(n.id,cid);s.link('use-'+n.id,n.from||'owner',n.id,cid,n.kind==='store'?'storage':'local-call');if(readAt===n.id)s.link('read','caller',n.id,prefix+'.read',mode);},[n.invariant],checks(n.checks));
  }
  b.api(command.method,command.path,JSON.stringify(command.request),JSON.stringify(command.response),command.errors,'owner');
  if(read)b.api(read.method,read.path,JSON.stringify(read.request),JSON.stringify(read.response),read.errors,readAt);
  for(const x of a.apis||[])b.api(x.method,x.path,JSON.stringify(x.request),JSON.stringify(x.response),x.errors,x.owner);
  for(const [i,algorithm]of a.code.entries())b.algorithm('mechanism-'+i,algorithm[0],algorithm[1],algorithm[2]);
  for(const c of a.cases){b.check(c.id,c.given,c.when,c.then,c.requirements);if(c.test)b.solution.acceptanceCases.at(-1).evidence={kind:'reference-test',testFile,testName:c.test};}
  const labels=new Map([['command',read?'commands':'invoke API'],['read','read-only query'],...a.steps.map(n=>['use-'+n.id,n.title])]);
  for(const stage of b.solution.stages){for(const op of stage.operations)if(op.edge)op.edge.label=labels.get(op.edge.id);for(const edge of stage.graph.edges)edge.label=labels.get(edge.id);}
 }
 return p;
}

